"""Literal pins for every derived member of corpus B (criterion 693).

Corpus B is ``verifier/conformance-vectors``. Each pin is a literal copied from
the published file, never recomputed; tamper vectors pin their tampered values.
asqav-11 pins the last-wins parse; asqav-05/10 carry a top-level policy_digest.
"""

from __future__ import annotations

import glob
import json
from functools import lru_cache
from pathlib import Path

import pytest

_CORPUS_ROOT = Path(__file__).parent.parent.parent / "verifier" / "conformance-vectors"


@lru_cache(maxsize=1)
def _receipts() -> dict[str, dict]:
    out = {}
    for path in sorted(glob.glob(str(_CORPUS_ROOT / "*" / "receipt.json"))):
        out[Path(path).parent.name] = json.loads(Path(path).read_text())
    return out


def _payload_of(receipt: dict) -> dict:
    payload = receipt.get("payload")
    assert isinstance(payload, dict), "expected a dict payload"
    return payload


def _sig_of(name: str, receipt: dict) -> str:
    """The `sig` string at `/signature/sig`, dsse's at `/signatures[0]/sig`."""
    if "#" in name:
        vector, _, index = name.partition("#signatures[")
        assert vector in _receipts(), name
        entry = _receipts()[vector]["signatures"][int(index.rstrip("]"))]
        assert isinstance(entry.get("sig"), str), name
        return entry["sig"]
    signature = receipt.get("signature")
    if isinstance(signature, str):  # flat spelling: the string is the sig
        return signature
    if not isinstance(signature, dict):  # hosted spelling: the object is renamed
        signature = receipt.get("signature_envelope")
    assert isinstance(signature, dict) and isinstance(signature.get("sig"), str), name
    return signature["sig"]


def _policy_digest_of(receipt: dict) -> str:
    payload = receipt.get("payload")
    if isinstance(payload, dict) and "policy_digest" in payload:
        return payload["policy_digest"]
    assert "policy_digest" in receipt, "policy_digest in neither payload nor top level"
    return receipt["policy_digest"]


#: Every derived member kind this file claims to pin. A kind appearing in the
#: corpus without a pin dict here fails `test_no_derived_member_escapes_a_pin`.
PINNED_MEMBER_NAMES = frozenset(
    {"sig", "action_ref", "policy_digest", "previousReceiptHash",
     "key_thumbprint", "payload_digest", "envelope_hash", "canonical"}
)

