def test_pin_counts_match_the_census() -> None:
    """Corpus growth fails here: a new vector must arrive with its pins."""
    actual = {
        "sig": len(PINNED_SIG),
        "action_ref": len(PINNED_ACTION_REF),
        "policy_digest": len(PINNED_POLICY_DIGEST),
        "previousReceiptHash": len(PINNED_PREV_HASH),
        "key_thumbprint": len(PINNED_KEY_THUMBPRINT),
        "payload_digest": len(PINNED_PAYLOAD_DIGEST),
        "envelope_hash": len(PINNED_ENVELOPE_HASH),
        "canonical": 0,
    }
    assert actual == EXPECTED_PIN_COUNTS, (
        f"pin census drifted: {actual} != {EXPECTED_PIN_COUNTS}"
    )


def _occurrences() -> list[tuple[str, str, str]]:
    """Every (vector, kind, location) holding a derived corpus member."""
    found = []
    for name, receipt in _receipts().items():
        payload = receipt.get("payload")
        if isinstance(payload, dict):
            for kind in ("action_ref", "policy_digest", "previousReceiptHash",
                         "key_thumbprint", "payload_digest"):
                if kind in payload and payload[kind] is not None:
                    found.append((name, kind, "payload"))
            binding = payload.get("counterparty_binding")
            if isinstance(binding, dict) and "envelope_hash" in binding:
                found.append((name, "envelope_hash", "counterparty_binding"))
        if "policy_digest" in receipt and not (
            isinstance(payload, dict) and "policy_digest" in payload
        ):
            found.append((name, "policy_digest", "<top>"))
        signature = receipt.get("signature")
        if isinstance(signature, dict) and isinstance(signature.get("sig"), str):
            found.append((name, "sig", "signature"))
        elif isinstance(signature, str) and isinstance(payload, dict):
            found.append((name, "sig", "signature"))
        envelope = receipt.get("signature_envelope")
        if isinstance(envelope, dict) and isinstance(envelope.get("sig"), str):
            found.append((name, "sig", "signature_envelope"))
        for index, entry in enumerate(receipt.get("signatures") or []):
            if isinstance(entry, dict) and isinstance(entry.get("sig"), str):
                found.append((name, "sig", f"signatures[{index}]"))
    return found


def test_no_derived_member_escapes_a_pin() -> None:
    """Both directions: every occurrence pinned, every pin still present."""
    by_kind = {
        "sig": PINNED_SIG,
        "action_ref": PINNED_ACTION_REF,
        "policy_digest": PINNED_POLICY_DIGEST,
        "previousReceiptHash": PINNED_PREV_HASH,
        "key_thumbprint": PINNED_KEY_THUMBPRINT,
        "payload_digest": PINNED_PAYLOAD_DIGEST,
        "envelope_hash": PINNED_ENVELOPE_HASH,
    }
    assert set(by_kind) | {"canonical"} == PINNED_MEMBER_NAMES
    seen: dict[str, set[str]] = {kind: set() for kind in by_kind}
    for name, kind, where in _occurrences():
        key = f"{name}#{where}" if where.startswith("signatures[") else name
        assert key in by_kind[kind], f"{name}: {kind} at {where} has no pin"
        seen[kind].add(key)
    for kind, pins in by_kind.items():
        stale = set(pins) - seen[kind]
        assert not stale, f"{kind}: pins with no corpus member: {sorted(stale)}"


def test_no_derived_member_hides_at_an_unknown_path() -> None:
    """A derived kind appearing somewhere new must be pinned deliberately."""
    known = {
        "action_ref": {"payload"},
        "policy_digest": {"payload", "<top>"},
        "previousReceiptHash": {"payload"},
        "key_thumbprint": {"payload"},
        "payload_digest": {"payload"},
        "envelope_hash": {"payload/counterparty_binding"},
        "sig": {"signature", "signature_envelope", "signatures[]"},
        "canonical": set(),
    }
    assert set(known) == PINNED_MEMBER_NAMES
    bad = []

    def hunt(node: object, trail: list[str], vector: str) -> None:
        if isinstance(node, dict):
            for key, value in node.items():
                if key in known:
                    loc = "/".join(trail) if trail else "<top>"
                    if key == "sig":
                        loc = "signatures[]" if trail and trail[-1].startswith("signatures[") else (trail[-1] if trail else "<top>")
                    elif key == "envelope_hash":
                        loc = "payload/counterparty_binding"
                    elif key == "policy_digest":
                        loc = "payload" if trail == ["payload"] else "<top>"
                    else:
                        loc = trail[-1] if trail else "<top>"
                    if loc not in known[key]:
                        bad.append(f"{vector}: {key} at {loc or '<top>'}")
                hunt(value, trail + [key], vector)
        elif isinstance(node, list):
            for index, value in enumerate(node):
                hunt(value, trail[:-1] + [f"{trail[-1]}[{index}]"] if trail else [], vector)

    for vector, receipt in _receipts().items():
        hunt(receipt, [], vector)
    assert bad == [], f"derived members at unknown paths: {bad}"

